try{const key='hanzi-reading-room-v2',raw=localStorage.getItem(key);if(raw&&!JSON.parse(raw).learningLab&&!localStorage.getItem(key+'-before-practice-v1'))localStorage.setItem(key+'-before-practice-v1',raw)}catch{}
const LAB_SKILLS=['recognition','writing','listening','shape','words','comprehension'];
const LAB_MODES={ear:['Listen & choose','Press Play, then find the written character.'],mixed:['Chapter run','Read, build, write, and use a sentence.'],boss:['Chapter encounter','A longer mixed challenge with a clear finish.'],story:['Story mission','Make decisions across a short original story.'],comic:['Mini comic','Follow three illustrated conversation panels.'],scene:['Everyday Chinese','Read messages, menus, signs, and schedules.'],dialogue:['Dialogue mission','Choose what to say to complete your goal.'],parts:['Build the character','Put the parts in the right positions.'],transform:['Change the shape','Add or change strokes to make a new character.'],duel:['Lookalike duel','Pick the right character among similar shapes.'],sound:['Sound → character','Connect familiar pinyin to the written form.'],dictation:['Listen & write','Press Play, then write the character.'],cloze:['Complete the sentence','Use context to fill the missing character.'],fonts:['Different fonts','Recognize the same character across type styles.'],homophones:['Same sound, different word','Use meaning to distinguish matching readings.'],words:['Word trail','Use words built from characters you have studied.'],comeback:['Welcome-back set','A short mix of familiar and difficult characters.'],deck:['My study deck','Practice your own vocabulary.']};
const LAB_SHOP=[{id:'pond',kind:'habitat',name:'Quiet pond',cost:8},{id:'lanterns',kind:'habitat',name:'Lantern hill',cost:14},{id:'bamboo',kind:'decor',name:'Bamboo',cost:4},{id:'lantern',kind:'decor',name:'Paper lantern',cost:6},{id:'stones',kind:'decor',name:'Stepping stones',cost:4},{id:'moon',kind:'skin',name:'Moonlit surface',cost:10},{id:'paper',kind:'skin',name:'Paper surface',cost:10}];
const LAB_ABILITIES=[{id:'roots',name:'Roots',skill:'shape',need:5,description:'A component clue for a shape challenge.'},{id:'echo',name:'Echo',skill:'listening',need:5,description:'An extra sound clue, only when you ask.'},{id:'scribe',name:'Scribe',skill:'writing',need:5,description:'A model to help with a writing challenge.'},{id:'guide',name:'Guide',skill:'comprehension',need:5,description:'A translation clue in a story.'}];
function labDefaults(){return {version:1,stats:{},days:{},runs:{},mistakes:{},retained:[],decks:[],images:{},abilities:{},unlocked:['grove','plain'],habitat:'grove',decor:[],skin:'plain',stamps:0,spent:0,claimed:[],history:[],paper:null}}
function labText(v,max=200){return typeof v==='string'?v.trim().slice(0,max):''}
function labNum(v,max=1e7){return Number.isFinite(v)&&v>=0?Math.min(max,Math.floor(v)):0}
function labPlain(v){return v&&typeof v==='object'&&!Array.isArray(v)?v:{}}
function labValidate(raw){
 const out=labDefaults(),s=labPlain(raw);if(s.version!==1)return out;
 const chars=new Set(CARDS.map(c=>c.character)),courses=new Set(COURSE_REGISTRY.map(c=>c.id)),skills=new Set(LAB_SKILLS);
 for(const [key,value] of Object.entries(labPlain(s.stats)).slice(0,4000)){const v=labPlain(value);if(!skills.has(v.skill)||!courses.has(v.course)||typeof v.item!=='string'||v.item.length>120||key!==v.skill+'|'+v.item)continue;out.stats[key]={skill:v.skill,item:v.item,course:v.course,attempts:labNum(v.attempts),correct:Math.min(labNum(v.attempts),labNum(v.correct)),assisted:Math.min(labNum(v.attempts),labNum(v.assisted)),last:labNum(v.last),days:[...new Set((Array.isArray(v.days)?v.days:[]).filter(labDate))].sort().slice(-30)}}
 for(const [day,v] of Object.entries(labPlain(s.days)).sort().slice(-45)){if(!labDate(day))continue;const d=labPlain(v);out.days[day]={keys:[...new Set((Array.isArray(d.keys)?d.keys:[]).filter(x=>typeof x==='string'&&x.length<=150))].slice(0,150),xp:labNum(d.xp,120),stamps:labNum(d.stamps,20),skills:[...new Set((Array.isArray(d.skills)?d.skills:[]).filter(x=>skills.has(x)))],courses:[...new Set((Array.isArray(d.courses)?d.courses:[]).filter(x=>courses.has(x)))]}}
 for(const c of courses){const run=labValidateRun(s.runs?.[c],c);if(run)out.runs[c]=run}
 for(const [key,value] of Object.entries(labPlain(s.mistakes)).slice(0,600)){const v=labPlain(value);if(!chars.has(key))continue;out.mistakes[key]={count:labNum(v.count),last:labNum(v.last),skill:skills.has(v.skill)?v.skill:'recognition',note:labText(v.note,300),drawing:inkSafeStrokes(v.drawing),model:v.model===true}}
 let drawingBudget=12000;for(const m of Object.values(out.mistakes)){const points=m.drawing.reduce((n,stroke)=>n+stroke.length,0);if(points>drawingBudget)m.drawing=[];else drawingBudget-=points}
 out.retained=[...new Set((Array.isArray(s.retained)?s.retained:[]).filter(x=>typeof x==='string'&&Object.hasOwn(out.stats,x)))].slice(0,4000);
 out.decks=(Array.isArray(s.decks)?s.decks:[]).slice(0,10).map(labValidateDeck).filter(Boolean);out.decks=out.decks.filter((d,i,a)=>a.findIndex(x=>x.id===d.id)===i);
 let imageBytes=0;for(const [ch,img]of Object.entries(labPlain(s.images))){if(chars.has(ch)&&typeof img==='string'&&/^data:image\/(?:jpeg|png|webp);base64,[A-Za-z0-9+/=]+$/.test(img)&&img.length<60000&&imageBytes+img.length<=180000){out.images[ch]=img;imageBytes+=img.length}}
 const allowed=new Set(['grove','plain',...LAB_SHOP.map(x=>x.id)]);out.unlocked=[...new Set(['grove','plain',...(Array.isArray(s.unlocked)?s.unlocked:[]).filter(x=>allowed.has(x))])];out.habitat=['grove','pond','lanterns'].includes(s.habitat)&&out.unlocked.includes(s.habitat)?s.habitat:'grove';out.skin=['plain','moon','paper'].includes(s.skin)&&out.unlocked.includes(s.skin)?s.skin:'plain';out.decor=[...new Set((Array.isArray(s.decor)?s.decor:[]).filter(x=>['bamboo','lantern','stones'].includes(x)&&out.unlocked.includes(x)))];out.stamps=labNum(s.stamps,1e5);out.spent=Math.min(out.stamps,labNum(s.spent,1e5));out.claimed=[...new Set((Array.isArray(s.claimed)?s.claimed:[]).filter(x=>typeof x==='string'&&/^[a-z0-9:-]{1,100}$/.test(x)))].slice(-500);
 for(const id of ['dragon','phoenix','turtle'])out.abilities[id]=[...new Set((Array.isArray(s.abilities?.[id])?s.abilities[id]:[]).filter(x=>LAB_ABILITIES.some(a=>a.id===x)))];
 out.history=(Array.isArray(s.history)?s.history:[]).slice(-60).map(labPlain).filter(v=>courses.has(v.course)&&COURSE_REGISTRY.find(c=>c.id===v.course).lessons.includes(v.lesson)&&Object.hasOwn(LAB_MODES,v.mode)).map(v=>({course:courses.has(v.course)?v.course:'chinese-1',lesson:COURSE_REGISTRY.some(c=>c.lessons.includes(v.lesson))?v.lesson:'I',mode:Object.hasOwn(LAB_MODES,v.mode)?v.mode:'mixed',right:labNum(v.right,30),total:labNum(v.total,30),helped:labNum(v.helped,30),at:labNum(v.at)}));
 const p=s.paper;if(p&&chars.has(p.character)&&courses.has(p.course))out.paper={course:p.course,character:p.character,pos:0,strokes:inkSafeStrokes(p.strokes),freeCopies:p.freeCopies?.key===p.character?{key:p.character,pos:0,count:labNum(p.freeCopies.count,999),items:(Array.isArray(p.freeCopies.items)?p.freeCopies.items:[]).slice(-3).map(inkSafeStrokes)}:null,model:p.model===true,started:labNum(p.started),elapsed:labNum(p.elapsed,3600000),timed:false};return out;
}
function labDate(d){return typeof d==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(d)}
function labValidateDeck(value){const d=labPlain(value);if(!/^[a-z0-9-]{1,60}$/.test(d.id||''))return null;const entries=(Array.isArray(d.entries)?d.entries:[]).slice(0,100).map((value,i)=>{const w=labPlain(value);return {id:'w'+i,zh:labText(w.zh,24),traditional:labText(w.traditional,24),py:labText(w.py,120),en:labText(w.en,200),context:labText(w.context,300)}}).filter(w=>w.zh&&/[\u3400-\u9fff]/.test(w.zh)&&w.en);return entries.length?{id:d.id,name:labText(d.name,60)||'My vocabulary',entries,created:labNum(d.created)}:null}
function labValidateRun(value,course){const r=labPlain(value);if(r.course!==course||!Object.hasOwn(LAB_MODES,r.mode)||!COURSE_REGISTRY.find(c=>c.id===course).lessons.includes(r.lesson)||!/^[a-z0-9-]{1,80}$/.test(r.id||'')||!Array.isArray(r.queue)||!r.queue.length||r.queue.length>30)return null;const queue=r.queue.map(q=>({mode:Object.hasOwn(LAB_MODES,q?.mode)?q.mode:'',item:labText(q?.item,120),variant:labNum(q?.variant,30)}));if(queue.some(q=>!q.mode||!q.item))return null;const pos=labNum(r.pos,30);if(pos>queue.length)return null;const done=pos===queue.length,feedback=!done&&r.feedback&&typeof r.feedback.correct==='boolean'?{correct:r.feedback.correct,helped:r.feedback.helped===true,chosen:Number.isInteger(r.feedback.chosen)?r.feedback.chosen:null,xp:0,key:queue[pos].item}:null;return {id:r.id,course,lesson:r.lesson,mode:r.mode,queue,pos,right:Math.min(pos+Number(!!feedback),labNum(r.right,30)),helped:Math.min(pos+Number(!!feedback),labNum(r.helped,30)),misses:(Array.isArray(r.misses)?r.misses:[]).filter(x=>typeof x==='string'&&x.length<=120).slice(0,30),done,feedback,usedHint:r.usedHint===true,helpKind:r.helpKind==='translation'?'translation':'',revealed:false,partChoices:[],started:labNum(r.started),savedAt:labNum(r.savedAt),abilityUsed:r.abilityUsed===true,deck:labText(r.deck,60),credited:done&&r.credited===true}}
function labData(){return state.learningLab??=labDefaults()}
function labToday(){const d=labData(),day=dayKey();return d.days[day]??={keys:[],xp:0,stamps:0,skills:[],courses:[]}}
function labRecord(skill,item,correct,helped=false,options={}){
 if(!LAB_SKILLS.includes(skill)||!item)return 0;const d=labData(),key=skill+'|'+item,now=Date.now(),today=dayKey();
 const v=d.stats[key]??={skill,item,course:selectedCourseId,attempts:0,correct:0,assisted:0,last:0,days:[]};v.attempts++;v.last=now;if(correct&&!helped){v.correct++;if(!v.days.includes(today))v.days.push(today);v.days=v.days.slice(-30)}if(helped)v.assisted++;
 if(v.days.length>=3&&new Date(v.days.at(-1)+'T12:00:00')-new Date(v.days[0]+'T12:00:00')>=7*86400000&&!d.retained.includes(key))d.retained.push(key);
 const ch=options.character;if(ch&&cardByChar[ch]&&(!correct||helped)){const m=d.mistakes[ch]??={count:0,last:0,skill,note:'',drawing:[],model:false};m.count++;m.last=now;m.skill=skill}
 const creditKey=skill+'|'+(options.creditItem||item),day=labToday();if(!day.courses.includes(selectedCourseId))day.courses.push(selectedCourseId);if(!day.skills.includes(skill))day.skills.push(skill);
 let earned=0;if(correct&&!helped&&!day.keys.includes(creditKey)&&day.keys.length<150){day.keys.push(creditKey);if(options.reward){earned=Math.max(0,Math.min(8,120-day.xp));day.xp+=earned;if(earned>0){bxGainXP(earned,{quiet:true});awardXP('lab:'+creditKey,3)}if(day.stamps<20){day.stamps++;d.stamps++}}}
 for(const old of Object.keys(d.days).sort().slice(0,-45))delete d.days[old];save();return earned;
}
const labLegacySeen=new WeakMap();
function labRecordLegacy(scope,pos,skill,item,correct,helped){let seen=labLegacySeen.get(scope);if(!seen){seen=new Set();labLegacySeen.set(scope,seen)}const k=pos+'|'+skill+'|'+item;if(seen.has(k))return;seen.add(k);const key=skill+'|'+item,u=undoAnswers.at(-1),day=dayKey(),ch=[...item].length===1?item:null;if(u?.scope===scope)u.labBefore={key,record:labData().stats[key]?clone(labData().stats[key]):null,day,dayRecord:labData().days[day]?clone(labData().days[day]):null,retained:[...labData().retained],ch,mistake:ch&&labData().mistakes[ch]?clone(labData().mistakes[ch]):null};labRecord(skill,item,correct,helped,{character:ch})}
function labUndo(u){const before=u.labBefore;if(!before)return;const d=labData();if(before.record)d.stats[before.key]=before.record;else delete d.stats[before.key];if(before.dayRecord)d.days[before.day]=before.dayRecord;else delete d.days[before.day];d.retained=before.retained;if(before.ch){if(before.mistake)d.mistakes[before.ch]=before.mistake;else delete d.mistakes[before.ch]}labLegacySeen.delete(u.scope)}
function labResetRuntime(){labReplayToken++;labVoiceToken++;try{labVoice?.abort?.()}catch{}clearTimeout(labPaperTimer);labPaperTimer=null;labVoice=null;labRun=null;labPaper=null;labSelectedLesson=null}
function labHomeAction(){const r=labData().runs[selectedCourseId];if(r&&!r.done&&(!savedResume||r.savedAt>(savedResume.savedAt||0)))return {eyebrow:'Saved chapter run',title:LAB_MODES[r.mode][0],copy:lessonLabel(r.lesson)+' · question '+(r.pos+1)+' / '+r.queue.length,button:'Resume chapter run',action:'labResume()',meta:'Saved practice'};if(!savedResume&&labGapDays()>=7&&labScopeCards(courseFocusId()).some(c=>state.cards[c.character]?.seen>0))return {eyebrow:'Welcome back',title:'Start with something familiar',copy:'A short set of familiar shapes and a few that need attention.',button:'Ease back in',action:"labStart('comeback')",meta:'Return practice'};return null}
function labSkillSummary(skill){const records=Object.values(labData().stats).filter(v=>v.skill===skill),attempts=records.reduce((n,v)=>n+v.attempts,0),correct=records.reduce((n,v)=>n+v.correct,0),helped=records.reduce((n,v)=>n+v.assisted,0);return {attempts,correct,helped,percent:attempts?Math.round(correct/attempts*100):0,items:records.filter(v=>v.correct>0).length}}
function labGapDays(){const dates=Object.keys(state.activity).filter(k=>(state.activity[k].cards||0)+(state.activity[k].readings||0)>0).sort();return dates.length?Math.max(0,Math.floor((new Date(dayKey()+'T12:00:00')-new Date(dates.at(-1)+'T12:00:00'))/86400000)):0}
function labAdaptiveMode(){const scored=LAB_SKILLS.map(skill=>({skill,...labSkillSummary(skill)})).filter(v=>v.attempts>=3).sort((a,b)=>a.percent-b.percent);const low=scored[0];return low?{mode:{recognition:'duel',writing:'dictation',listening:'ear',shape:'parts',words:'words',comprehension:'cloze'}[low.skill],reason:low.skill+' has your lowest recorded independent accuracy ('+low.percent+'%).'}:{mode:'mixed',reason:'Try a short run across reading, shape, writing, and sentences.'}}
